-- Aggregate statistics on new, outstanding, and performance characteristics of US residential mortgages drawn from the NMDB 5% national sample, published at national, regional, state, and metro levels.
-- Auto-generated by scripts/gen_evidence_pages.py: 19,054,246 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("RELEASE_DATE") as year, count(*) as records
from THE_LIBRARY.HOUSING.FED_FHFA_NMDB
where "RELEASE_DATE" is not null
group by 1
order by 1
